-- Table and RLS for Bank ATMs (Банкомати во Македонија)
CREATE TABLE IF NOT EXISTS public.bank_atms (
  id text PRIMARY KEY,
  name text NOT NULL,
  bank text NOT NULL,
  bank_slug text NOT NULL,
  city text NOT NULL,
  city_slug text NOT NULL,
  address text NOT NULL,
  location_description text,
  latitude double precision NOT NULL,
  longitude double precision NOT NULL,
  is_24_7 boolean DEFAULT true,
  working_hours text DEFAULT '24/7',
  has_deposit boolean DEFAULT false,
  currency text DEFAULT 'MKD',
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- Indexes for lightning-fast querying by city and bank
CREATE INDEX IF NOT EXISTS idx_bank_atms_city ON public.bank_atms (city);
CREATE INDEX IF NOT EXISTS idx_bank_atms_bank_slug ON public.bank_atms (bank_slug);
CREATE INDEX IF NOT EXISTS idx_bank_atms_coords ON public.bank_atms (latitude, longitude);

ALTER TABLE public.bank_atms ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'bank_atms' AND policyname = 'Allow public read for bank_atms'
  ) THEN
    CREATE POLICY "Allow public read for bank_atms" ON public.bank_atms FOR SELECT USING (true);
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'bank_atms' AND policyname = 'Allow service role write for bank_atms'
  ) THEN
    CREATE POLICY "Allow service role write for bank_atms" ON public.bank_atms FOR ALL USING (true);
  END IF;
END $$;

GRANT ALL ON public.bank_atms TO service_role;
GRANT SELECT ON public.bank_atms TO anon, authenticated;

